 const updateCollection=(kind,fn)=>a.update(d=>{const key=kind==='contact'?'contacts':'documents';d[key]=d[key]||clone(kind==='contact'?sampleContacts:samples);fn(d[key])});
 const upload=async file=>{if(!file)return;if(!/\.(pdf|docx|png|jpe?g|webp|txt)$/i.test(file.name))return a.notify(a.T('Choose PDF, DOCX, PNG, JPG, WebP or TXT.','בחרו PDF, DOCX, PNG, JPG, WebP או TXT.'));if(file.size>10*1024*1024)return a.notify(a.T('Choose a file under 10 MB.','בחרו קובץ עד 10 MB.'));setUploading(true);try{const fileId=id();await putLocalFile(fileId,file);const record={id:id(),fileId,filename:file.name,title:file.name.replace(/\.[^.]+$/,''),he:file.name.replace(/\.[^.]+$/,''),mime:file.type||'application/octet-stream',size:file.size,category:'Home',ownerId:a.user,visibility:'private',allowedIds:[],date:anchor};updateCollection('document',list=>list.push(record));setSelected(record.id);setEditor({...record,kind:'document'});a.notify(a.cloud?a.T('File uploaded. Choose how to share it.','הקובץ הועלה. בחרו איך לשתף אותו.'):a.T('File saved on this device. Choose how to share it.','הקובץ נשמר במכשיר הזה. בחרו איך לשתף אותו.'))}catch{a.notify(a.T('The file could not be saved. Check device storage.','לא ניתן לשמור את הקובץ. בדקו מקום באחסון המכשיר.'))}finally{setUploading(false)}};
 const openFile=async(record,download=false)=>{let blob;try{blob=record.fileId?await getLocalFile(record.fileId):await fetch(record.sampleUrl).then(r=>{if(!r.ok)throw new Error();return r.blob()});if(!blob)throw new Error();const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;if(download||!['application/pdf','image/png','image/jpeg','image/webp','text/plain'].includes(record.mime))link.download=record.filename;else{link.target='_blank';link.rel='noopener noreferrer'}link.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{a.notify(a.T('File is unavailable on this device. Upload it again or connect cloud storage.','הקובץ לא זמין במכשיר הזה. העלו אותו שוב או חברו אחסון בענן.'))}};
 const save=e=>{e.preventDefault();if(!editor?.title.trim())return;if(editor.visibility==='selected'&&!editor.allowedIds.length)return a.notify(a.T('Choose who to share with.','בחרו עם מי לשתף.'));updateCollection(editor.kind,list=>{const next={...editor,he:editor.title};delete next.kind;const index=list.findIndex(r=>r.id===next.id);if(index>=0)list[index]=next;else list.push(next)});setSelected(editor.id);setEditor(null);a.notify(a.T('Saved.','נשמר.'))};
