function Metric({label,value,icon:MetricIcon}){return <div className={'metric '+(MetricIcon?'with-icon':'')}>{MetricIcon&&<span className="metric-icon"><MetricIcon size={42}/></span>}<div><span>{label}</span><strong>{typeof value==='string'&&value.startsWith('₪')?<><span className="currency">₪</span>{value.slice(1)}</>:value}</strong></div></div>}

function Statistics({shopping=false}){return <StatisticsView app={useApp()} shopping={shopping} ui={{Heading,Button,Badge,Tabs,Scope,Avatar,Icon,Switch,Empty,ActivityHeatmap,HouseholdStatistics}}/>}

function HouseholdStatistics({range}){const a=useApp();if(a.member(a.user).role==='child')return <Empty text={a.T('Household finance statistics are available to adult profiles.','נתוני הכספים של הבית זמינים לפרופילי מבוגרים.')}/>;const records=a.visible(a.data.expenses||[]).filter(e=>inRange(e.date,anchor,range)),total=records.reduce((n,e)=>n+e.amount,0),categories=rankBy(records,r=>r.title).map(r=>({name:a.text(r.records[0]),amount:r.records.reduce((n,e)=>n+e.amount,0)})),budget=a.data.preferences.monthlyBudget||(a.cloud?0:4000);return <><div className="metric-row"><Metric label={a.T('Expenses in this period','הוצאות בתקופה הזאת')} value={'₪'+total.toLocaleString()}/><Metric label={a.T('Monthly budget','תקציב חודשי')} value={'₪'+budget.toLocaleString()}/><Metric label={a.T('Budget used','ניצול התקציב')} value={budget?Math.round(total/budget*100)+'%':'—'}/></div><section className="chart-section"><h2>{a.T('Expenses by category','הוצאות לפי קטגוריה')}</h2><div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={categories}><CartesianGrid stroke="var(--border)" vertical={false}/><XAxis dataKey="name" tick={{fill:'var(--muted)',fontSize:13}}/><YAxis tick={{fill:'var(--muted)',fontSize:13}}/><Tooltip contentStyle={{background:'var(--surface)',color:'var(--text)'}}/><Bar isAnimationActive={false} dataKey="amount" fill="var(--primary)" radius={[12,12,0,0]}/></BarChart></ResponsiveContainer></div></section><Button secondary onClick={()=>a.go('household/expenses')}>{a.T('Open expense ledger','פתיחת רישום ההוצאות')}</Button></>}


